import{_ as t,o as r,c as e,a5 as n}from"./chunks/framework.BZzouRtU.js";const o="/study/images/graphics/keyframes-and-animation.svg",p=JSON.parse('{"title":"キーフレームとアニメーションの基本 — 時間から値を決める","description":"","frontmatter":{"title":"キーフレームとアニメーションの基本 — 時間から値を決める","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"箱を動かす例から、時刻と値を記録するキーフレーム、補間、カーブ、クリップ、ループを説明する。描画のFPSや回転の補間との関係も調べる。","aliases":["アニメーション","animation","キーフレーム","keyframe","トラック","チャンネル","補間","animation curve","カーブ","クリップ","ループ","slerp"],"verification":"Unity 6.0のアニメーションクリップ・カーブとKhronosのglTF 2.0アニメーション仕様に照合（2026-11-07）"}},"headers":[],"relativePath":"graphics/basics/keyframes-and-animation.md","filePath":"graphics/basics/keyframes-and-animation.md"}'),i={name:"graphics/basics/keyframes-and-animation.md"};function s(l,a,h,d,m,g){return r(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="キーフレームとアニメーションの基本-—-時間から値を決める" tabindex="-1">キーフレームとアニメーションの基本 — 時間から値を決める <a class="header-anchor" href="#キーフレームとアニメーションの基本-—-時間から値を決める" aria-label="Permalink to &quot;キーフレームとアニメーションの基本 — 時間から値を決める&quot;">​</a></h1><p>箱の位置を時刻ごとに決め、その順に表示すると、左から右へ動かせます。<strong>アニメーション</strong>は、位置、回転、形、色などを時間に応じて変える仕組みです。ここでは箱のX位置だけを変えます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/AnimationClips.html" target="_blank" rel="noreferrer">Unityのアニメーションクリップ</a></p><h2 id="どの時刻に、どの値にするかを記録する" tabindex="-1">どの時刻に、どの値にするかを記録する <a class="header-anchor" href="#どの時刻に、どの値にするかを記録する" aria-label="Permalink to &quot;どの時刻に、どの値にするかを記録する&quot;">​</a></h2><p><strong>キーフレーム</strong>は、ある時刻に置く値や姿勢を指定するものです。例えば「0秒でX位置0」「1秒でX位置2」という二つのキーを用意できます。位置、回転、色など、動かす対象の項目を<strong>プロパティー</strong>と呼びます。その項目の時間変化を、トラックやチャンネルにまとめて扱います。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/animeditor-AnimationCurves.html" target="_blank" rel="noreferrer">Unityのカーブとキー</a></p><table tabindex="0"><thead><tr><th>クリップ内の時刻</th><th>X位置</th><th>この例での扱い</th></tr></thead><tbody><tr><td>0秒</td><td>0</td><td>記録したキー。</td></tr><tr><td>0.5秒</td><td>1</td><td>二つのキーから線形補間で求めた値。</td></tr><tr><td>1秒</td><td>2</td><td>記録したキー。</td></tr></tbody></table><p>キーの間を計算で埋めるのが<strong>補間</strong>です。<strong>線形補間</strong>では、時間の進み具合に比例して値を変えます。この例の0.5秒は区間の半分なので、X位置も0と2の中間の1になります。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#animations" target="_blank" rel="noreferrer">glTFの時間と補間</a></p><figure class="study-figure"><img src="'+o+'" alt="0秒のX位置0と1秒のX位置2をキーとして記録する。線形補間では、その間の0.5秒でX位置1になる。グラフは横軸が時間、縦軸がX位置で、両端のキーを直線で結んでいる。" width="760" height="470" loading="lazy"><figcaption>中央は、キーの間を評価した位置です。<a href="/study/images/graphics/keyframes-and-animation.svg" target="_blank" rel="noopener noreferrer">キーと補間の図を拡大</a></figcaption></figure><h2 id="カーブの形で、変化の速さも変わる" tabindex="-1">カーブの形で、変化の速さも変わる <a class="header-anchor" href="#カーブの形で、変化の速さも変わる" aria-label="Permalink to &quot;カーブの形で、変化の速さも変わる&quot;">​</a></h2><p>時間を横軸、値を縦軸に描いたものを<strong>アニメーションカーブ</strong>と呼びます。直線なら一定の割合で値が変わり、曲線にすると出だしをゆっくりにしたり、途中を速くしたりできます。キーの値が同じでも、間の計算方法が変われば動きが変わります。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/animeditor-AnimationCurves.html" target="_blank" rel="noreferrer">Unityのアニメーションカーブ</a></p><p>例えばglTFには、次のキーまで値を保つ<code>STEP</code>、直線的に変える<code>LINEAR</code>、接線の情報も使う<code>CUBICSPLINE</code>があります。どの方法が使えるか、端の外側をどう扱うかは、ファイル形式や再生側の仕様で確認します。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#animation-sampler-interpolation" target="_blank" rel="noreferrer">glTFの補間モード</a></p><h2 id="クリップは、ひとまとまりの動き" tabindex="-1">クリップは、ひとまとまりの動き <a class="header-anchor" href="#クリップは、ひとまとまりの動き" aria-label="Permalink to &quot;クリップは、ひとまとまりの動き&quot;">​</a></h2><p><strong>アニメーションクリップ</strong>は、「歩く」「扉を開く」など、時間変化をまとめたデータです。一つのクリップに、複数のボーンの回転や、物体の位置など、複数の項目を含められます。ゲーム側は再生するクリップ、速度、開始時刻などを選び、現在の時刻に対応する値を使います。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/AnimationClips.html" target="_blank" rel="noreferrer">Unityのクリップ</a></p><p><strong>ループ再生</strong>では、終端へ来た後に先頭へ戻して再生を続けます。歩行をなめらかにつなぐなら、終わりと始まりの姿勢や動く速さも確認します。箱をX位置0から2へ動かした例をそのまま戻せば、継ぎ目で位置が0へ戻ります。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/LoopingAnimationClips.html" target="_blank" rel="noreferrer">Unityのループするクリップの設定</a></p><h2 id="タイムラインのフレーム番号と、描画のfps" tabindex="-1">タイムラインのフレーム番号と、描画のFPS <a class="header-anchor" href="#タイムラインのフレーム番号と、描画のfps" aria-label="Permalink to &quot;タイムラインのフレーム番号と、描画のFPS&quot;">​</a></h2><p>制作ツールでは、時間を<strong>フレーム番号</strong>でも表します。例えば開始をフレーム0、基準を毎秒30フレームとするタイムラインなら、フレーム15は0.5秒です。これは制作時の時刻の表し方です。ゲーム側で画像を何回描くかというFPSは、別に数えます。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/animeditor-UsingAnimationEditor.html" target="_blank" rel="noreferrer">UnityのAnimationウィンドウ</a> · <a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a></p><p>キーが0秒と1秒にしかなくても、再生側は0.1秒や0.2秒など、必要な時刻で値を評価できます。glTFではキーの入力時刻を秒で記録します。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#animation-sampler-input" target="_blank" rel="noreferrer">glTFのキーの時刻</a></p><p>図を使って確かめるなら、0.25秒と0.75秒の値を求めます。この線形補間ではX位置はそれぞれ0.5と1.5です。次に、キー間を一定の値で保つ方式へ変えると、1秒に達する前はX位置0のままになります。</p><h2 id="回転は、表現と補間の規則も見る" tabindex="-1">回転は、表現と補間の規則も見る <a class="header-anchor" href="#回転は、表現と補間の規則も見る" aria-label="Permalink to &quot;回転は、表現と補間の規則も見る&quot;">​</a></h2><p>回転では、向きの表し方と、どちらへ回るかも関わります。例えば角度350度から10度へ回すとき、数値をそのまま直線でつなぐ場合と、短い経路で向きをつなぐ場合では動きが違います。glTFの回転は<strong>クォータニオン</strong>で記録し、線形モードの回転には球面線形補間（slerp）の使用が推奨されています。一周以上回したいときは、途中のキーなどで意図を表す必要があります。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#interpolation-slerp" target="_blank" rel="noreferrer">glTFの回転の補間</a> · <a href="/study/math/rendering/quaternion.html">クォータニオンの詳解</a></p><h2 id="関連する仕組み" tabindex="-1">関連する仕組み <a class="header-anchor" href="#関連する仕組み" aria-label="Permalink to &quot;関連する仕組み&quot;">​</a></h2><p>キャラクターの腕や脚を動かす仕組みは、<a href="/study/graphics/basics/rigs-and-skinning.html">リグとスキニング</a>へ進みます。位置や回転の基準は、<a href="/study/graphics/basics/transforms-and-cameras.html">座標変換とカメラ</a>で確認できます。</p>',21)])])}const f=t(i,[["render",s]]);export{p as __pageData,f as default};
